"""VEX Corpus Consistency Check - comprehensive analysis."""
import json
from collections import Counter

CORPUS = "C:/Users/User/vex-corpus/output/corpus"

print("=" * 70)
print("VEX CORPUS CONSISTENCY CHECK")
print("=" * 70)

chunks = []
with open(f"{CORPUS}/merged_corpus.jsonl", "r", encoding="utf-8") as f:
    for i, line in enumerate(f, 1):
        line = line.strip()
        if not line:
            continue
        try:
            chunks.append(json.loads(line))
        except json.JSONDecodeError as e:
            print(f"  [ERROR] Line {i}: JSON parse error: {e}")

with open(f"{CORPUS}/manifest.json", "r", encoding="utf-8") as f:
    manifest = json.load(f)
with open(f"{CORPUS}/stats.json", "r", encoding="utf-8") as f:
    stats = json.load(f)
with open(f"{CORPUS}/dedup_report.json", "r", encoding="utf-8") as f:
    dedup = json.load(f)
with open(f"{CORPUS}/prereq_graph.json", "r", encoding="utf-8") as f:
    prereq = json.load(f)

all_ids = set(c["id"] for c in chunks if "id" in c)

print("\n" + "=" * 70)
print("1. SCHEMA CONSISTENCY")
print("=" * 70)
required_fields = {"id", "source_id", "content_type", "difficulty"}
missing_required = []
no_code = []
all_fields = Counter()
for c in chunks:
    for fld in c:
        all_fields[fld] += 1
    miss = required_fields - set(c.keys())
    if miss:
        missing_required.append((c.get("id", "NO_ID"), miss))
    if not c.get("code_blocks") and not c.get("code"):
        no_code.append(c.get("id", "NO_ID"))

print(f"  Total chunks: {len(chunks)}")
print(f"  Chunks missing required fields: {len(missing_required)}")
for cid, miss in missing_required[:10]:
    print(f"    {cid}: missing {miss}")
print(f"  Chunks with no code_blocks/code: {len(no_code)}")
if no_code[:5]:
    print(f"    Examples: {no_code[:5]}")
print(f"\n  Field coverage (<100%):")
for field, count in sorted(all_fields.items(), key=lambda x: x[1]):
    pct = count / len(chunks) * 100
    if pct < 100:
        print(f"    {field}: {count}/{len(chunks)} ({pct:.1f}%)")

print("\n" + "=" * 70)
print("2. ID UNIQUENESS")
print("=" * 70)
id_counts = Counter(c.get("id", "NO_ID") for c in chunks)
dupes = {k: v for k, v in id_counts.items() if v > 1}
print(f"  Unique IDs: {len(id_counts)}")
print(f"  Duplicate IDs: {len(dupes)}")
for did, cnt in sorted(dupes.items(), key=lambda x: -x[1])[:20]:
    print(f"    {did}: appears {cnt} times")

print("\n" + "=" * 70)
print("3. LLM FIELD CONSISTENCY")
print("=" * 70)
llm_fields = ["llm_topic", "llm_bugs", "llm_complexity", "llm_code_quality", "llm_bottlenecks", "llm_secondary_topics"]
llm_field_counts = Counter()
has_any_llm = 0
for c in chunks:
    present = [f for f in llm_fields if f in c]
    if present:
        has_any_llm += 1
        for f in present:
            llm_field_counts[f] += 1

print(f"  Chunks with any LLM field: {has_any_llm}")
for f in llm_fields:
    print(f"    {f}: {llm_field_counts.get(f, 0)}")

partial_llm = []
for c in chunks:
    present = set(f for f in llm_fields if f in c)
    if present and present != set(llm_fields):
        missing = set(llm_fields) - present
        partial_llm.append((c["id"], sorted(present), sorted(missing)))
print(f"\n  Partial LLM fields: {len(partial_llm)}")
for cid, have, miss in partial_llm[:5]:
    print(f"    {cid}: has {have}, missing {miss}")
if len(partial_llm) > 5:
    print(f"    ... and {len(partial_llm) - 5} more")

complexity_values = Counter()
invalid_complexity = []
for c in chunks:
    if "llm_complexity" in c:
        val = c["llm_complexity"]
        complexity_values[val] += 1
        if not val.startswith("O("):
            invalid_complexity.append((c["id"], val))
print(f"\n  llm_complexity values:")
for val, cnt in sorted(complexity_values.items(), key=lambda x: -x[1]):
    print(f"    {val}: {cnt}")
if invalid_complexity:
    print(f"  Invalid complexity values:")
    for cid, val in invalid_complexity[:10]:
        print(f"    {cid}: '{val}'")
empty_llm_topic = [c["id"] for c in chunks if c.get("llm_topic", None) == ""]
print(f"  Empty string llm_topic: {len(empty_llm_topic)}")

print("\n" + "=" * 70)
print("4. TIER 2 FIELD CONSISTENCY (prompt/explanation)")
print("=" * 70)
has_prompt = sum(1 for c in chunks if c.get("prompt"))
has_explanation = sum(1 for c in chunks if c.get("explanation"))
prompt_no_expl = [c["id"] for c in chunks if c.get("prompt") and not c.get("explanation")]
expl_no_prompt = [c["id"] for c in chunks if c.get("explanation") and not c.get("prompt")]
empty_prompt = [c["id"] for c in chunks if "prompt" in c and c["prompt"] == ""]
empty_expl = [c["id"] for c in chunks if "explanation" in c and c["explanation"] == ""]
print(f"  Chunks with prompt: {has_prompt}")
print(f"  Chunks with explanation: {has_explanation}")
print(f"  Has prompt but NO explanation: {len(prompt_no_expl)}")
for cid in prompt_no_expl[:5]:
    print(f"    {cid}")
print(f"  Has explanation but NO prompt: {len(expl_no_prompt)}")
for cid in expl_no_prompt[:5]:
    print(f"    {cid}")
print(f"  Empty string prompt: {len(empty_prompt)}")
print(f"  Empty string explanation: {len(empty_expl)}")

short_expl = [(c["id"], len(c["explanation"]), c["explanation"][:80])
              for c in chunks if c.get("explanation") and len(c["explanation"]) < 50]
print(f"\n  Short explanations (<50 chars): {len(short_expl)}")
for cid, length, text in short_expl[:15]:
    print(f"    {cid} ({length}ch): \"{text}\"")
if len(short_expl) > 15:
    print(f"    ... and {len(short_expl) - 15} more")

print("\n" + "=" * 70)
print("5. CROSS-REFERENCE: manifest/stats vs actual")
print("=" * 70)
print(f"  stats total_chunks: {stats['total_chunks']} | actual: {len(chunks)} | {'MATCH' if stats['total_chunks'] == len(chunks) else 'MISMATCH'}")

actual_by_source = Counter(c.get("source_id", "unknown") for c in chunks)
print(f"\n  by_source:")
for src in sorted(set(list(stats.get("by_source", {}).keys()) + list(actual_by_source.keys()))):
    s = stats.get("by_source", {}).get(src, "N/A")
    a = actual_by_source.get(src, "N/A")
    print(f"    {src}: stats={s}, actual={a} [{'MATCH' if s == a else 'MISMATCH'}]")

actual_by_type = Counter(c.get("content_type", "unknown") for c in chunks)
print(f"\n  by_content_type:")
for ct in sorted(set(list(stats.get("by_content_type", {}).keys()) + list(actual_by_type.keys()))):
    s = stats.get("by_content_type", {}).get(ct, "N/A")
    a = actual_by_type.get(ct, "N/A")
    print(f"    {ct}: stats={s}, actual={a} [{'MATCH' if s == a else 'MISMATCH'}]")

actual_by_diff = Counter(c.get("difficulty", "unknown") for c in chunks)
print(f"\n  by_difficulty:")
for d in sorted(set(list(stats.get("by_difficulty", {}).keys()) + list(actual_by_diff.keys()))):
    s = stats.get("by_difficulty", {}).get(d, "N/A")
    a = actual_by_diff.get(d, "N/A")
    print(f"    {d}: stats={s}, actual={a} [{'MATCH' if s == a else 'MISMATCH'}]")

manifest_ids = set(c["id"] for c in manifest.get("chunks", []))
print(f"\n  manifest chunk count: {len(manifest_ids)} | corpus unique IDs: {len(all_ids)} | {'MATCH' if len(manifest_ids) == len(all_ids) else 'MISMATCH'}")
mfm = all_ids - manifest_ids
mfc = manifest_ids - all_ids
if mfm:
    print(f"  In corpus but NOT manifest: {len(mfm)}")
    for cid in sorted(mfm)[:5]:
        print(f"    {cid}")
if mfc:
    print(f"  In manifest but NOT corpus: {len(mfc)}")
    for cid in sorted(mfc)[:5]:
        print(f"    {cid}")

actual_with_code = sum(1 for c in chunks if c.get("code_blocks") or c.get("code"))
print(f"\n  stats with_code: {stats.get('with_code', 'N/A')} | actual: {actual_with_code} | {'MATCH' if stats.get('with_code') == actual_with_code else 'MISMATCH'}")

print("\n" + "=" * 70)
print("6. DEDUP REPORT")
print("=" * 70)
dedup_clusters = dedup.get("clusters", [])
dedup_ids = set()
invalid_dedup = set()
for cluster in dedup_clusters:
    for cid in cluster:
        dedup_ids.add(cid)
        if cid not in all_ids:
            invalid_dedup.add(cid)
print(f"  Total clusters: {len(dedup_clusters)}")
print(f"  Total IDs in dedup: {len(dedup_ids)}")
print(f"  Invalid IDs (not in corpus): {len(invalid_dedup)}")
for cid in sorted(invalid_dedup)[:10]:
    print(f"    {cid}")
if len(invalid_dedup) > 10:
    print(f"    ... and {len(invalid_dedup) - 10} more")

print("\n" + "=" * 70)
print("7. PREREQ GRAPH")
print("=" * 70)
prereq_concepts = set(prereq.get("concept_intros", {}).keys())
invalid_prereq_intro = set()
for concept, ids in prereq.get("concept_intros", {}).items():
    for cid in ids:
        if cid not in all_ids:
            invalid_prereq_intro.add(cid)

invalid_prereq_edge = set()
for cid, deps in prereq.get("prerequisites", {}).items():
    if cid not in all_ids:
        invalid_prereq_edge.add(cid)
    for dep in deps:
        if dep not in all_ids:
            invalid_prereq_edge.add(dep)

print(f"  Concepts: {sorted(prereq_concepts)}")
print(f"  Invalid IDs in concept_intros: {len(invalid_prereq_intro)}")
for cid in sorted(invalid_prereq_intro)[:10]:
    print(f"    {cid}")
print(f"  Invalid IDs in prerequisite edges: {len(invalid_prereq_edge)}")
for cid in sorted(invalid_prereq_edge)[:10]:
    print(f"    {cid}")
if len(invalid_prereq_edge) > 10:
    print(f"    ... and {len(invalid_prereq_edge) - 10} more")

print("\n" + "=" * 70)
print("8. DATA QUALITY")
print("=" * 70)
for field in ["llm_topic", "prompt", "explanation", "title", "content"]:
    empties = [c["id"] for c in chunks if field in c and c[field] == ""]
    if empties:
        print(f"  Empty string '{field}': {len(empties)} chunks")
        for cid in empties[:3]:
            print(f"    {cid}")

empty_cb = [c["id"] for c in chunks if c.get("code_blocks") == []]
print(f"  Empty code_blocks list: {len(empty_cb)}")
empty_created = sum(1 for c in chunks if c.get("created_at") == "")
print(f"  Empty created_at: {empty_created}")

suspicious_bugs = []
for c in chunks:
    if c.get("llm_bugs"):
        code_text = ""
        for cb in c.get("code_blocks", []):
            code_text += cb.get("code", "")
        if c.get("code"):
            code_text += c["code"]
        for bug in c["llm_bugs"]:
            desc = bug.get("description", "")
            if "pcopen" in desc.lower() and "pcopen" not in code_text.lower():
                suspicious_bugs.append((c["id"], desc, code_text[:60]))
            elif "pcclose" in desc.lower() and "pcopen" not in code_text.lower():
                suspicious_bugs.append((c["id"], desc, code_text[:60]))
print(f"\n  Suspicious LLM bugs (reference absent functions): {len(suspicious_bugs)}")
for cid, bug, code in suspicious_bugs[:15]:
    print(f"    {cid}: bug='{bug}' | code='{code}'")
if len(suspicious_bugs) > 15:
    print(f"    ... and {len(suspicious_bugs) - 15} more")

print("\n" + "=" * 70)
print("9. TOPIC TAXONOMY")
print("=" * 70)
topics = Counter(c.get("llm_topic") for c in chunks if c.get("llm_topic"))
print(f"  Unique llm_topic values: {len(topics)}")
for topic, cnt in sorted(topics.items(), key=lambda x: -x[1]):
    print(f"    {topic}: {cnt}")

topic_list = sorted(topics.keys())
potential_dupes = []
for i, t1 in enumerate(topic_list):
    for t2 in topic_list[i+1:]:
        n1 = t1.lower().replace("_", " ").strip()
        n2 = t2.lower().replace("_", " ").strip()
        if n1 == n2:
            potential_dupes.append((t1, t2))
        elif n1 + "s" == n2 or n2 + "s" == n1:
            potential_dupes.append((t1, t2))
        elif n1.rstrip("s") == n2.rstrip("s") and abs(len(n1) - len(n2)) <= 1:
            potential_dupes.append((t1, t2))
if potential_dupes:
    print(f"\n  Potential duplicate topics:")
    for t1, t2 in potential_dupes:
        print(f"    '{t1}' ({topics[t1]}) vs '{t2}' ({topics[t2]})")
else:
    print(f"\n  No obvious duplicate topics found.")

topic_code_mismatch = []
for c in chunks:
    if c.get("llm_topic") == "point_cloud_ops":
        code_text = ""
        for cb in c.get("code_blocks", []):
            code_text += cb.get("code", "")
        pc_funcs = ["pcopen", "pcfind", "pcclose", "pcfilter", "pcimport", "pcgenerate", "pgfind", "nearpoints"]
        if not any(fn in code_text.lower() for fn in pc_funcs):
            topic_code_mismatch.append((c["id"], code_text[:80]))
if topic_code_mismatch:
    print(f"\n  'point_cloud_ops' tagged but no pc* functions: {len(topic_code_mismatch)}")
    for cid, code in topic_code_mismatch[:10]:
        print(f"    {cid}: code='{code}'")
    if len(topic_code_mismatch) > 10:
        print(f"    ... and {len(topic_code_mismatch) - 10} more")

print("\n" + "=" * 70)
print("SUMMARY")
print("=" * 70)
issues = []
if dupes: issues.append(f"CRITICAL: {len(dupes)} duplicate IDs")
if missing_required: issues.append(f"CRITICAL: {len(missing_required)} chunks missing required fields")
if invalid_dedup: issues.append(f"WARNING: {len(invalid_dedup)} invalid IDs in dedup_report")
if invalid_prereq_intro: issues.append(f"WARNING: {len(invalid_prereq_intro)} invalid IDs in prereq concept_intros")
if invalid_prereq_edge: issues.append(f"WARNING: {len(invalid_prereq_edge)} invalid IDs in prereq edges")
if suspicious_bugs: issues.append(f"WARNING: {len(suspicious_bugs)} LLM bugs reference absent functions")
if topic_code_mismatch: issues.append(f"WARNING: {len(topic_code_mismatch)} chunks with topic/code mismatch")
if len(manifest_ids) != len(all_ids): issues.append(f"WARNING: manifest ({len(manifest_ids)}) != corpus ({len(all_ids)}) ID count")
if stats["total_chunks"] != len(chunks): issues.append(f"WARNING: stats total ({stats['total_chunks']}) != actual ({len(chunks)})")
if partial_llm: issues.append(f"INFO: {len(partial_llm)} chunks with partial LLM fields")
if no_code: issues.append(f"INFO: {len(no_code)} chunks have no code")
if short_expl: issues.append(f"INFO: {len(short_expl)} short explanations (<50 chars)")
if empty_created: issues.append(f"INFO: {empty_created} chunks with empty created_at")
if potential_dupes: issues.append(f"INFO: {len(potential_dupes)} potential duplicate topic names")

for issue in issues:
    print(f"  {issue}")
if not issues:
    print("  No issues found!")
print(f"\n  Total chunks analyzed: {len(chunks)}")
print("=" * 70)
PYEOF

